	s(fEval, `thread.active[f]++\n\treturn nil`, `return nil`, `enterFunction: the call is not counted`)

	// ---- sizes
	s(fAlloc, `const frameFreeSlots = 64`, `const frameFreeSlots = 1 << 20`, `frames: no charge`)
	s(fAlloc, `const frameFreeSlots = 64`, `const frameFreeSlots = 8`, `frames: charge from 8 slots`)
