	s(fValue, `if depth >= pathSetDepth {\n\t\tn += 8`, `if depth >= pathSetDepth {\n\t\tn += 0`, `DeepFormWork: push below 32 is free`)
	s(fForm, `const formProbe = 4096`, `const formProbe = 1 << 20`, `formProbe 1M`)
	s(fForm, `const formProbe = 4096`, `const formProbe = 16`, `formProbe 16`)
	s(fHash, `if len(s) >= 12 {`, `if len(s) >= 16 {`, `hashString: wyhash from 16`)
