	s(fJSON, `if m.units-m.charged >= flushWork {`, `if m.units-m.charged > flushWork {`, `json workMeter.add: > flushWork`)
	s(fJSON, `\tm.charged = m.units\n\treturn m.th.ChargeWork(n)`, `\treturn m.th.ChargeWork(n)`, `json workMeter.flush: charged not recorded`)

